const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const manitoba = ee.FeatureCollection("FAO/GAUL/2015/level1")
        .filter(ee.Filter.eq('ADM1_NAME', 'Manitoba'));
    if (manitoba.size().getInfo() === 0) {
        console.log("Failed to load geometry for Manitoba.");
        console.log("D");
        return;
    }
    const geometry = manitoba.geometry();
    const dateStart = '2025-08-03';
    const dateEnd = '2025-08-04';

    // 2. Data Acquisition & Check
    // MODIS Daily Fire Product (MOD14A1) is suitable.
    // The FireMask band identifies fire pixels (classes 7, 8, 9).
    const fireCollection = ee.ImageCollection('MODIS/061/MOD14A1')
        .filterDate(dateStart, dateEnd)
        .filterBounds(geometry);

    const collectionSize = fireCollection.size().getInfo();
    if (collectionSize === 0) {
        console.log(`No MODIS fire images found for ${dateStart}.`);
        console.log("C1");
        return;
    }
    console.log(`Found ${collectionSize} image(s) for the specified date.`);

    // 3. Processing
    const image = fireCollection.first(); // Use the single image for the day
    const fireMask = image.select('FireMask');

    // Create a binary image: 1 for fire (low, nominal, high confidence), 0 otherwise.
    // Class 7: low-confidence fire
    // Class 8: nominal-confidence fire
    // Class 9: high-confidence fire
    const firePixels = fireMask.gte(7);

    // 4. Calculation
    // Use ee.Reducer.frequencyHistogram to count fire pixels.
    // This is more memory-efficient for sparse data like fires than summing over a large area.
    const fireHistogram = firePixels.reduceRegion({
        reducer: ee.Reducer.frequencyHistogram(),
        geometry: geometry,
        scale: 1000, // Native resolution is 1km
        maxPixels: 1e9
    });

    const fireCounts = ee.Dictionary(fireHistogram.get('FireMask'));
    if (fireCounts.getInfo() === null) {
        console.log("Could not calculate fire pixel histogram. The region may be empty.");
        console.log("C2");
        return;
    }

    // The histogram returns counts for each value. We are interested in value '1' (fire).
    // If no '1' key exists, it means there are no fire pixels.
    const numberOfFires = ee.Number(fireCounts.get('1', 0)).getInfo(); // Default to 0 if no fires

    if (numberOfFires === null || isNaN(numberOfFires)) {
        console.log("Fire count calculation resulted in an invalid number.");
        console.log("C3");
        return;
    }

    // 5. Validation & Final Answer
    console.log(`Date: ${dateStart}`);
    console.log(`Region: Manitoba, Canada`);
    console.log(`Active fire pixels detected: ${numberOfFires}`);
    console.log(`Threshold: > 30`);

    if (numberOfFires > 30) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, (err) => {
                console.error('Authentication error:', err);
