            ee.initialize(null, null, resolve, (err) => {
                console.error('Initialization error:', err);
                reject(err);
            });
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during the analysis:', e);
        console.log("D");
    }
}

